// Safely extract and validate project description
const desc = event.body?.project_description;

if (!desc || typeof desc !== 'string' || desc.trim().length === 0) {
  throw new Error("Invalid or missing field: project_description");
}

return {
  project_description: desc.trim()
};

// Return complete structured pipeline results in one body
return {
  status: "success",
  project_description: steps.extract_input.project_description,
  discovered_risks: steps.discover_risks,
  scored_risks: steps.score_risks,
  themes: steps.cluster_themes,
  mitigations: steps.generate_mitigations,
  summary: steps.generate_summary,
  final_report: steps.assemble_final_report
};
